def find_peak_altitude(altitudes: list[int]) -> int:
    if not altitudes:
        return 0
    peak = altitudes[0]
    for a in altitudes[1:]:
        if a > peak:
            peak = a
    return peak

def apply_loyalty_bonus(points: list[float]) -> float:
    if not points:
        return 0.0
    total = sum(p for p in points if p > 0)
    if total >= 200.0:
        total *= 1.1
    return round(total, 2)

def group_consecutive_tags(tags: list[str]) -> list[tuple[str, int]]:
    if not tags:
        return []
    grouped: list[tuple[str, int]] = []
    curr = tags[0]
    count = 1
    for t in tags[1:]:
        if t == curr:
            count += 1
        else:
            grouped.append((curr, count))
            curr = t
            count = 1
    grouped.append((curr, count))
    return grouped
